            migrationState = .migrating
            // ... migration logic with progress updates

            // Step 4: Verify
            migrationState = .verifying
            // ... verification logic

            migrationState = .completed

        } catch let migrationError as MigrationError {
            error = migrationError
            migrationState = .failed
